// test/fixtures/wackySheets.ts
// Thirty deliberately odd client tear sheets for accuracy testing of the induction engine.
// Each carries genuine financial lines (some plainly labelled, some quirkily) alongside niche
// sections and strange "non-negotiables" that a real desk might insist on. Ground truth per
// sheet:
//   expectMapped   concept keys the engine SHOULD bind (the label is a known synonym)
//   expectAbstain  substrings of lines it must NOT map (niche / non-financial / uncovered)
//   currency       the currency the engine should detect (£->GBP, $->USD, EUR->EUR, else GBP)
//   skeletonHas    section headings the engine should detect (optional)
// The honesty contract predicts: precision on mapped fields is 100% (a niche line never maps),
// recall is bounded by the dictionary's synonym coverage (odd-but-real labels abstain, and
// those are the recall gaps a feedback loop would later close).

export interface WackySheet {
  name: string;
  text: string;
  expectMapped: string[];
  expectAbstain: string[];
  currency: "GBP" | "USD" | "EUR";
  skeletonHas?: string[];
}

